@startuml

class Location {}

class Exhibition {
  + OpeningDate : date
}

class ExhibitionItem {
  + Description : string
}

class Piece {
  + Description : string
}

class Collector {
  + Name : string
}

class Employee {
  + Name : string
}

Location "1" -- "*" Exhibition
Exhibition "1" -- "1" Employee : coordinator
Exhibition "1" -- "*" ExhibitionItem
ExhibitionItem "*" -- "1" Collector : requested from
ExhibitionItem "1" -- "*" Piece : sourced from
Employee "0..1" -- "0..1" Employee : coach

@enduml

